import {archive} from './service.js';
import {categories,characters,clans,villages,teams,abilities,beasts,akatsuki,kara} from './data.js';
const app=document.querySelector('#app');let path=location.pathname.replace(/\/$/,'')||'/',searchOpen=false,query='',activeResult=0,filters={};
const route=(p)=>{history.pushState({},'',p);path=p;filters={};render();scrollTo({top:0,behavior:'smooth'})};
const esc=(s)=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const link=(p,label,cls='')=>`<a href="${p}" class="${cls}" data-route>${label}</a>`;
const title=(eyebrow,name,desc='')=>`<div class="page-heading"><p class="eyebrow">${eyebrow} <span>／</span> 忍者</p><h1>${name}</h1>${desc?`<p class="muted">${desc}</p>`:''}<span class="heading-rule"></span></div>`;
const footer=()=>`<footer><div class="footer-mark">忍</div><div><h2>The Shinobi World is waiting.</h2><p>An independent fan archive of the shinobi world.</p></div><div class="footer-links">${['Home','Characters','Clans','Villages','Akatsuki'].map((x,i)=>link(['/', '/characters','/clans','/villages','/akatsuki'][i],x)).join('')}</div><small>© SHINOBI ARCHIVES · 忍道</small></footer>`;
const nav=()=>`<header id="nav"><a href="/" data-route class="brand" aria-label="Shinobi Archives home"><span class="brand-mark" id="brand-mark">忍</span><span>SHINOBI<br><b>ARCHIVES</b></span></a><nav aria-label="Main navigation">${['Home','Characters','Clans','Villages','Teams','Akatsuki'].map((x,i)=>link(['/','/characters','/clans','/villages','/teams','/akatsuki'][i],x,path===['/','/characters','/clans','/villages','/teams','/akatsuki'][i]?'current':'')).join('')}</nav><button class="search-trigger" id="search-trigger" aria-label="Search the archive"><span>⌕</span> <span class="search-label">Search</span> <kbd>⌘ K</kbd></button><button class="menu-trigger" id="menu-trigger" aria-label="Open menu" aria-expanded="false">☰</button></header><div id="mobile-menu" class="mobile-menu" hidden>${categories.map(c=>link(c.path,c.name)).join('')}</div>`;
const characterCard=c=>link('/characters/'+c.id,`<div class="portrait portrait-${c.tone}"><span class="portrait-sigil">${c.mark}</span><span class="portrait-figure"></span><span class="portrait-label">${c.jp}</span></div><div class="character-info"><span class="micro">${c.village} · ${c.rank}</span><h3>${c.name}</h3><p>${c.clan} clan <span aria-hidden="true">↗</span></p></div>`,'character-card');
const tile=(item,path,meta)=>link(path,`<div class="tile-head"><span class="tile-symbol">${item.symbol}</span><span class="tile-arrow">↗</span></div><div><span class="micro">${meta}</span><h3>${item.name}</h3><p>${item.description||item.role||item.native||''}</p></div>`,'archive-tile');
const home=()=>`<main><section class="hero" id="hero"><div class="hero-art"></div><div class="hero-mist"></div><div class="hero-symbol">忍</div><div class="particles" aria-hidden="true">${Array.from({length:18},(_,i)=>`<i style="--i:${i};--x:${(i*67)%100}%;--y:${(i*47)%90}%"></i>`).join('')}</div><div class="hero-content"><p class="eyebrow">THE HIDDEN WORLD · VOL. 01</p><h1>SHINOBI<br><em>ARCHIVES</em></h1><p class="hero-sub">Explore the Naruto Universe</p><p class="hero-copy">Characters. Clans. Villages. Legends.</p>${link('/characters','EXPLORE THE SHINOBI WORLD <span>↗</span>','button-primary')}</div><div class="hero-side">忍道 <span>／</span> THE WAY OF THE NINJA</div><a href="#explore" class="scroll-cue">SCROLL TO EXPLORE <span>↓</span></a></section><section class="section explore" id="explore">${title('01 · THE ARCHIVE','Explore the Shinobi World','Eight paths into a world built on bonds, power and legacy.')}<div class="category-grid">${categories.map((c,i)=>link(c.path,`<div class="category-top"><span class="category-number">0${i+1}</span><span class="category-symbol">${c.symbol}</span></div><div><small>${String(c.count).padStart(2,'0')} RECORDS</small><h3>${c.name}</h3><p>${c.desc}</p></div><span class="category-arrow">↗</span>`,'category-card')).join('')}</div></section><section class="feature-section section"><div>${title('02 · THE PEOPLE','The Will of Fire','Every legend begins with a name.')}<p class="feature-copy">From the next generation of heroes to those who chose the shadows, discover the shinobi who changed history.</p>${link('/characters','VIEW ALL CHARACTERS ↗','text-link')}</div><div class="featured-cards">${characters.slice(0,3).map(characterCard).join('')}</div></section><section class="world-section section"><div>${title('03 · THE FIVE NATIONS','A world beyond the Leaf','Trace the hidden villages across the shinobi world.')} ${link('/villages','EXPLORE THE MAP ↗','text-link')}</div><div class="world-orbit"><span>木</span><small>FIVE GREAT SHINOBI COUNTRIES</small></div></section><section class="section"><div class="section-line"><div>${title('04 · INHERITED POWER','Bloodlines & forbidden arts')}</div>${link('/kekkei-genkai','OPEN THE SECRET FILES ↗','text-link')}</div><div class="mini-grid">${abilities.slice(0,3).map(a=>tile(a,'/kekkei-genkai/'+a.id,a.type)).join('')}</div></section><section class="section beast-feature"><div>${title('05 · THE LIVING LEGENDS','Power with a name','Nine spirits. Nine stories.')} ${link('/tailed-beasts','DISCOVER THE TAILED BEASTS ↗','text-link')}</div><div class="beast-nine">九<span>KURAMA · NINE TAILS</span></div></section><section class="section shadow-feature"><div>${title('06 · IN THE SHADOWS','The Akatsuki','Those who move within the shadows.')} ${link('/akatsuki','ENTER THE SHADOWS ↗','text-link')}</div><div class="shadow-cloud">暁</div></section></main>`;
const filtersHtml=()=>`<div class="filter-bar"><label class="search-field"><span>⌕</span><input id="character-search" type="search" placeholder="Search shinobi..." value="${esc(filters.text||'')}" aria-label="Search shinobi"></label>${[['village','Village', [...new Set(characters.map(c=>c.village))]],['clan','Clan',[...new Set(characters.map(c=>c.clan))]],['rank','Rank',[...new Set(characters.map(c=>c.rank))]],['nature','Nature Type',[...new Set(characters.flatMap(c=>c.nature))]],['affiliation','Affiliation',[...new Set(characters.map(c=>c.affiliation))]]].map(([key,label,values])=>`<label class="select-wrap"><span class="sr-only">${label}</span><select data-filter="${key}"><option value="">${label}</option>${values.map(v=>`<option ${filters[key]===v?'selected':''}>${esc(v)}</option>`).join('')}</select></label>`).join('')}</div><p class="result-count" id="result-count"></p><div class="character-grid" id="character-grid"></div>`;
function updateCharacters(){const items=characters.filter(c=>(!filters.text||c.name.toLowerCase().includes(filters.text.toLowerCase()))&&['village','clan','rank','affiliation'].every(k=>!filters[k]||c[k]===filters[k])&&(!filters.nature||c.nature.includes(filters.nature)));document.querySelector('#result-count').textContent=`${items.length} SHINOBI FOUND`;document.querySelector('#character-grid').innerHTML=items.length?items.map(characterCard).join(''):`<div class="empty">No shinobi match these filters. <button id="clear-filters">Clear filters</button></div>`}
const characterDetail=c=>`<main class="detail"><div class="detail-hero"><div class="detail-image portrait-${c.tone}"><span class="detail-kanji">${c.mark}</span><span class="portrait-figure"></span></div><div class="detail-intro"><p class="eyebrow">SHINOBI FILE / ${c.id.toUpperCase()}</p><h1>${c.name}</h1><p class="jp-name">${c.jp}</p><p class="lead">${c.bio}</p><div class="facts">${[['VILLAGE',c.village],['CLAN',c.clan],['RANK',c.rank],['TEAM',c.team],['AFFILIATION',c.affiliation]].map(([a,b])=>`<div><small>${a}</small><strong>${b}</strong></div>`).join('')}</div></div></div><div class="detail-sections"><section><h2>PROFILE <span>01</span></h2><p>${c.bio}</p><h2>ABILITIES <span>02</span></h2><div class="chips">${c.abilities.map(x=>`<span>${x}</span>`).join('')}</div><h2>NATURE TYPES <span>03</span></h2><div class="chips">${c.nature.map(x=>`<span>${x}</span>`).join('')}</div><h2>JUTSU <span>04</span></h2><ul class="record-list">${c.abilities.map(x=>`<li>${x}<span>↗</span></li>`).join('')}</ul><h2>FAMILY · TEAMS · AFFILIATIONS <span>05</span></h2><p>${c.family.length?c.family.join(' · '):'No family records'} · ${c.team} · ${c.affiliation}</p>${c.abilities.some(a=>/Sharingan|Byakugan|Rinnegan/.test(a))?`<div class="secret-banner">血継限界 <strong>KEKKEI GENKAI DETECTED</strong></div>`:''}</section><aside class="stats"><p class="eyebrow">COMBAT DATABOOK</p><h2>SHINOBI STATS</h2><p class="muted">Attribute ratings · 0 to 5</p>${['Ninjutsu','Taijutsu','Genjutsu','Intelligence','Strength','Speed','Stamina','Hand Seals'].map((s,i)=>`<div class="stat"><div><span>${s}</span><b>${c.stats[i]}.0</b></div><div class="track"><span style="width:${c.stats[i]*20}%"></span></div></div>`).join('')}</aside></div><div class="back-link">${link('/characters','← BACK TO CHARACTERS','text-link')}</div></main>`;
const villageMap=()=>`<div class="map"><div class="map-contours"></div><span class="map-label">THE FIVE GREAT NATIONS <small>忍界地図</small></span>${villages.map(v=>`<button class="map-pin" style="left:${v.x}%;top:${v.y}%" data-village="${v.id}" aria-label="Explore ${v.name}"><span>${v.symbol}</span><small>${v.name}</small><div class="pin-tooltip">${v.country} · ${v.count} shinobi</div></button>`).join('')}</div>`;
const detailGeneric=(item,type)=>`<main class="section generic-detail">${link('/'+type,'← BACK TO ARCHIVE','text-link')}<div class="generic-hero"><span class="generic-symbol">${item.symbol}</span><div>${title('CLASSIFIED FILE / '+type.toUpperCase(),item.name,item.description||item.native||'')}<p class="jp-name">${item.country||item.village||item.type||''}</p></div></div><div class="info-panels">${Object.entries(item).filter(([k])=>!['id','name','symbol','description','native','x','y','tone'].includes(k)).map(([k,v])=>`<section><h2>${k.replace(/([A-Z])/g,' $1').toUpperCase()}</h2><p>${Array.isArray(v)?v.join(' · '):v}</p></section>`).join('')}</div>${type==='clans'?`<h2 class="subhead">KNOWN MEMBERS</h2><div class="relation-list">${item.members.map((m,i)=>`<div><span>0${i+1}</span><strong>${m}</strong><span>◯</span></div>`).join('')}</div>`:''}${type==='villages'?`<h2 class="subhead">SHINOBI OF THE VILLAGE</h2><div class="character-grid">${characters.filter(c=>c.village.toLowerCase()===item.id).map(characterCard).join('')||'<p>No records yet.</p>'}</div>`:''}</main>`;
const listing=(name,eyebrow,desc,body)=>`<main class="section listing">${title(eyebrow,name,desc)}${body}</main>`;
const current=()=>{const parts=path.split('/').filter(Boolean),type=parts[0],id=parts[1];if(path==='/')return home();if(type==='characters')return id?(archive.get('characters',id)?characterDetail(archive.get('characters',id)):notFound()):listing('Characters','01 · SHINOBI RECORDS','Browse the people behind the legends.',filtersHtml());if(type==='villages')return id?(archive.get(type,id)?detailGeneric(archive.get(type,id),type):notFound()):listing('The Hidden Villages','03 · WORLD MAP','Select a village to open its archive.',villageMap()+`<div class="mini-grid">${villages.map(v=>tile(v,'/villages/'+v.id,v.country)).join('')}</div>`);if(type==='clans')return id?(archive.get(type,id)?detailGeneric(archive.get(type,id),type):notFound()):listing('Legendary Clans','02 · BLOODLINES','Legacies written across generations.',`<div class="mini-grid">${clans.map(c=>tile(c,'/clans/'+c.id,c.village+' · '+c.members.length+' known members')).join('')}</div>`);if(type==='teams')return id?(archive.get(type,id)?detailGeneric(archive.get(type,id),type):notFound()):listing('Shinobi Teams','04 · THE BONDS','The people who fight together.',`<div class="mini-grid">${teams.map(t=>tile(t,'/teams/'+t.id,t.village+' · '+t.leader)).join('')}</div>`);if(type==='kekkei-genkai')return id?(archive.get('abilities',id)?detailGeneric(archive.get('abilities',id),type):notFound()):listing('Kekkei Genkai','05 · CLASSIFIED','Inherited power. Secret knowledge.',`<div class="mini-grid">${abilities.map(a=>tile(a,'/kekkei-genkai/'+a.id,a.type+' · '+a.users.length+' users')).join('')}</div>`);if(type==='tailed-beasts')return id?(archive.get('beasts',id)?detailGeneric(archive.get('beasts',id),type):notFound()):listing('Tailed Beasts','06 · BIJŪ','Nine living legends.',`<div class="beast-grid">${beasts.map(b=>link('/tailed-beasts/'+b.id,`<span class="beast-symbol">${b.symbol}</span><div><small>${b.tails} ${b.tails===1?'TAIL':'TAILS'} · JINCHŪRIKI ${b.host}</small><h3>${b.name}</h3><p>${b.description}</p><div class="tails">${Array.from({length:9},(_,i)=>`<i class="${i<b.tails?'on':''}"></i>`).join('')}</div></div>`,'beast-card')).join('')}</div>`);if(type==='akatsuki'||type==='kara'){let arr=type==='akatsuki'?akatsuki:kara;return id?(archive.get(type,id)?detailGeneric(archive.get(type,id),type):notFound()):`<main class="section listing shadow-page">${title('07 · ORGANIZATIONS',type==='akatsuki'?'Akatsuki':'Kara',type==='akatsuki'?'Those who move within the shadows.':'A new force within the shadows.')}<div class="mini-grid">${arr.map(a=>tile(a,'/'+type+'/'+a.id,a.role)).join('')}</div></main>`}return notFound()};
const notFound=()=>`<main class="not-found"><div>煙</div><p class="eyebrow">LOST IN THE HIDDEN WORLD</p><h1>404</h1><p>This shinobi could not be found.</p>${link('/','RETURN TO KONOHA ↗','button-primary')}</main>`;
function searchMarkup(){const results=query.trim()?archive.search(query.trim()).slice(0,12):[...characters.slice(0,3).map(x=>({...x,type:'characters'})),...villages.slice(0,2).map(x=>({...x,type:'villages'}))];return `<div class="search-overlay" id="search-overlay"><div class="command" role="dialog" aria-modal="true" aria-label="Search the Shinobi World"><div class="command-input"><span>⌕</span><input id="global-search" placeholder="Search the Shinobi World..." value="${esc(query)}" autocomplete="off"><button id="close-search" aria-label="Close search">ESC</button></div><div class="command-results">${query.toLowerCase()==='dattebayo'?'<div class="dattebayo">DATTEBAYO! ✦ Believe it.</div>':''}${results.length?results.map((r,i)=>`<a href="/${r.type==='abilities'?'kekkei-genkai':r.type==='beasts'?'tailed-beasts':r.type}/${r.id}" data-route class="command-row ${i===activeResult?'active':''}" data-index="${i}"><span>${r.symbol||r.mark||'忍'}</span><div><small>${r.type.toUpperCase()}</small><strong>${r.name}</strong></div><b>↗</b></a>`).join(''):'<p class="command-empty">No records found.</p>'}</div><div class="command-hint">↑ ↓ Navigate <span>↵ Open</span> <span>ESC Close</span></div></div></div>`}
function render(){document.title=(path==='/'?'Shinobi Archives':path.split('/').filter(Boolean).map(x=>x.replaceAll('-',' ')).join(' · ')+' — Shinobi Archives');app.innerHTML=nav()+current()+footer()+(searchOpen?searchMarkup():'');document.body.classList.toggle('searching',searchOpen);if(path==='/characters')updateCharacters();if(searchOpen){let input=document.querySelector('#global-search');input?.focus();input?.setSelectionRange(input.value.length,input.value.length)}observe();onScroll()}
function observe(){if(!('IntersectionObserver'in window))return;const observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');observer.unobserve(e.target)}}),{threshold:.08});document.querySelectorAll('.section,.character-card,.archive-tile,.category-card,.beast-card').forEach(el=>observer.observe(el))}
function onScroll(){document.querySelector('#nav')?.classList.toggle('scrolled',scrollY>40);let hero=document.querySelector('#hero');if(hero&&!matchMedia('(prefers-reduced-motion: reduce)').matches)hero.style.setProperty('--scroll',Math.min(scrollY/innerHeight,1))}
addEventListener('scroll',onScroll,{passive:true});addEventListener('popstate',()=>{path=location.pathname.replace(/\/$/,'')||'/';render()});document.addEventListener('click',e=>{const a=e.target.closest('a[data-route]');if(a){e.preventDefault();searchOpen=false;route(a.getAttribute('href'));return}if(e.target.closest('#search-trigger')){searchOpen=true;query='';activeResult=0;render()}if(e.target.id==='search-overlay'||e.target.closest('#close-search')){searchOpen=false;render()}if(e.target.closest('#menu-trigger')){const menu=document.querySelector('#mobile-menu');menu.hidden=!menu.hidden;e.target.closest('button').setAttribute('aria-expanded',String(!menu.hidden))}if(e.target.closest('[data-village]'))route('/villages/'+e.target.closest('[data-village]').dataset.village);if(e.target.closest('#clear-filters')){filters={};render()}if(e.target.closest('#brand-mark')){let n=+(sessionStorage.getItem('leafTap')||0)+1;sessionStorage.setItem('leafTap',n);if(n%5===0){document.querySelector('.brand-mark')?.classList.add('chakra-burst');setTimeout(()=>document.querySelector('.brand-mark')?.classList.remove('chakra-burst'),1300)}}});
document.addEventListener('input',e=>{if(e.target.id==='character-search'){filters.text=e.target.value;updateCharacters()}if(e.target.id==='global-search'){query=e.target.value;activeResult=0;const pos=e.target.selectionStart;document.querySelector('.command-results').outerHTML=new DOMParser().parseFromString(searchMarkup(),'text/html').querySelector('.command-results').outerHTML;e.target.setSelectionRange(pos,pos)}});document.addEventListener('change',e=>{if(e.target.matches('[data-filter]')){filters[e.target.dataset.filter]=e.target.value;updateCharacters()}});
document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();searchOpen=!searchOpen;query='';render()}if(searchOpen){const rows=[...document.querySelectorAll('.command-row')];if(e.key==='Escape'){searchOpen=false;render()}if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();activeResult=(activeResult+(e.key==='ArrowDown'?1:-1)+rows.length)%rows.length;rows.forEach((r,i)=>r.classList.toggle('active',i===activeResult));rows[activeResult]?.scrollIntoView({block:'nearest'})}if(e.key==='Enter'&&rows.length){e.preventDefault();searchOpen=false;route(rows[activeResult].getAttribute('href'))}}else if(e.key.toLowerCase()==='n'&&!/input|textarea/i.test(document.activeElement.tagName)){document.body.classList.add('ninja-flash');setTimeout(()=>document.body.classList.remove('ninja-flash'),800)}});
addEventListener('pointermove',e=>{if(innerWidth<750||matchMedia('(prefers-reduced-motion: reduce)').matches)return;let hero=document.querySelector('#hero');if(hero){hero.style.setProperty('--mx',((e.clientX/innerWidth)-.5).toFixed(3));hero.style.setProperty('--my',((e.clientY/innerHeight)-.5).toFixed(3))}});render();
